#!/usr/bin/env python3
"""Versions the site's CSS/JS addresses and writes sw.js (the service worker).

    python3 .github/build_sw.py              rebuild: run this before every commit that changes the site
    python3 .github/build_sw.py --check DIR  exit 1 if DIR's version tags or sw.js are out of date
                                             (the pre-commit hook runs this on the staged files)

What it writes:
  1. In every page, every same-origin CSS/JS reference gets ?v=<hash of the file's contents>. A changed
     file gets a new address, so no cache can pair a new page with old CSS: not the browser's HTTP cache
     (GitHub Pages: max-age=600), not the copy Chrome keeps in memory and reuses on a normal reload (that
     reuse never reaches the service worker), not the worker's own caches.
  2. sw.js. It precaches the home page and the tabletop hub (once they exist), every tabletop tool page with
     everything it loads, the pack's CSS/JS/icons, and every font the stylesheets reference. CACHE_VERSION is a hash of the worker and every precached file, so any
     change to them changes sw.js and returning visitors get the new worker. The strategy is described in
     the header of sw.js.

Hook: the repo's hooks live in .githooks/. After cloning, run once:  git config core.hooksPath .githooks
"""
import glob, hashlib, json, os, re, sys

HOST = 'writing.builtbyjoshstudio.com'

TEMPLATE = r'''/* =========================================================
   SERVICE WORKER — offline support for %(host)s
   Generated by .github/build_sw.py from the pages that exist. Do not edit by hand:
   run  python3 .github/build_sw.py  (the pre-commit hook refuses a stale copy).

   HOW A RETURNING VISITOR GETS UPDATES
   · HTML pages: network-first. Online, every page request goes to the server
     and revalidates (cache: 'no-cache'), so a normal reload, or a click, shows
     the page as deployed. The saved copy is only the offline fallback.
   · Same-origin CSS and JS: every page asks for them at a versioned address
     (styles.css?v=<hash of the file>, written at build time), so a changed file
     has a new address that no cache holds: not the browser's 10-minute HTTP
     cache (GitHub Pages: max-age=600), not the copy Chrome keeps in memory and
     reuses on a normal reload (that reuse never reaches this worker), not the
     caches below. They are fetched network-first with 'no-cache' as well.
   · Fonts and images: from the cache, refreshed in the background
     (stale-while-revalidate). Every font is precached.
   · Anything else (analytics, other sites) is left to the browser.

   HOW OLD CACHES ARE CLEARED
   CACHE_VERSION is a hash of this worker and of every file it precaches, so a
   deploy that changes any of them changes this file. The browser checks for a
   new worker on page loads (the registering script asks on every load). The new worker:
     1. precaches fresh copies (cache: 'reload', nothing from the browser's cache);
     2. on activation, saves again the pages this visitor had opened (from the
        older caches and the open tabs, the first page visited included), so
        they still open offline;
     3. deletes every older jsw- cache, then takes over the open tabs.
   ========================================================= */
(function () {
  'use strict';
  var CACHE_VERSION = '%(version)s';
  var PAGES = 'jsw-pages-' + CACHE_VERSION;
  var ASSETS = 'jsw-assets-' + CACHE_VERSION;

  /* The home page and the tabletop hub (the manifest start_url) once they exist, and every tabletop tool
     page with everything it loads, so an installed app opens any tool offline; plus every font. */
  var SHELL_PAGES = %(pages)s;
  var SHELL_ASSETS = %(assets)s;

  var CODE = /\.(css|js)$/;
  function fresh(url) { return new Request(url, { cache: 'reload' }); }

  self.addEventListener('install', function (e) {
    e.waitUntil(
      Promise.all([
        caches.open(PAGES).then(function (c) { return c.addAll(SHELL_PAGES.map(fresh)); }),
        caches.open(ASSETS).then(function (c) { return c.addAll(SHELL_ASSETS.map(fresh)); })
      ]).then(function () { return self.skipWaiting(); })
    );
  });

  /* the pages this visitor has opened: everything in older page caches, plus every open tab
     (on the very first visit, the page that installed this worker) */
  function visitedPages() {
    return caches.keys().then(function (keys) {
      var old = keys.filter(function (k) { return k.indexOf('jsw-pages-') === 0 && k !== PAGES; });
      return Promise.all(old.map(function (k) {
        return caches.open(k).then(function (c) { return c.keys(); }).then(function (reqs) {
          return reqs.map(function (r) { return { url: r.url, from: k }; });
        });
      }));
    }).then(function (lists) {
      return self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (tabs) {
        var all = [].concat.apply([], lists);
        tabs.forEach(function (t) { all.push({ url: t.url, from: null }); });
        return all;
      });
    });
  }

  function keepVisitedPages() {
    return Promise.all([caches.open(PAGES), visitedPages()]).then(function (r) {
      var cache = r[0], seen = {};
      return Promise.all(r[1].map(function (p) {
        var u = new URL(p.url); u.hash = '';
        if (u.origin !== self.location.origin || seen[u.href]) return null;
        seen[u.href] = true;
        return cache.match(u.href).then(function (hit) {
          if (hit) return null;
          return fetch(fresh(u.href)).then(function (res) {
            if (!res || !res.ok || res.redirected) throw new Error('not saved');
            return cache.put(u.href, res);
          }).catch(function () {
            // offline while updating: keep the copy the older cache had
            if (!p.from) return null;
            return caches.open(p.from).then(function (c) { return c.match(u.href); })
              .then(function (old) { return old ? cache.put(u.href, old) : null; });
          });
        });
      }));
    });
  }

  self.addEventListener('activate', function (e) {
    e.waitUntil(
      keepVisitedPages().catch(function () {}).then(function () {
        return caches.keys();
      }).then(function (keys) {
        return Promise.all(keys.map(function (k) {
          if (k.indexOf('jsw-') === 0 && k !== PAGES && k !== ASSETS) return caches.delete(k);
          return null;
        }));
      }).then(function () { return self.clients.claim(); })
    );
  });

  /* ---- network-first: the live site wins, the saved copy covers the offline case ----
     cache: 'no-cache' makes the browser ask the server every time (a 304 costs almost nothing),
     so a 10-minute HTTP cache can never pair a new page with old CSS.
     Offline: the exact address first; then ignoreSearch, so a shared or cross-tool handoff link
     (?weight=12&unit=lbs) still finds the page it was saved under. */
  function networkFirst(e, req, cacheName) {
    return fetch(req, { cache: 'no-cache' }).then(function (res) {
      if (res && res.ok && res.type === 'basic' && !res.redirected) {
        var copy = res.clone();
        e.waitUntil(caches.open(cacheName).then(function (c) { return c.put(req, copy); }));
      }
      return res;
    }).catch(function () {
      return caches.match(req).then(function (exact) {
        return exact || caches.match(req, { ignoreSearch: true });
      }).then(function (hit) {
        if (hit) return hit;
        return req.mode === 'navigate' ? offline() : Response.error();
      });
    });
  }

  /* ---- stale-while-revalidate: instant from the cache, refreshed in the background ---- */
  function staleWhileRevalidate(e, req) {
    return caches.open(ASSETS).then(function (cache) {
      return cache.match(req).then(function (hit) {
        var update = fetch(req).then(function (res) {
          if (res && res.ok) cache.put(req, res.clone());
          return res;
        }).catch(function () { return hit || Response.error(); });
        if (hit) { e.waitUntil(update); return hit; }
        return update;
      });
    });
  }

  /* ---- shown when a page that was never opened is requested with no network ---- */
  function offline() {
    // no colour values here: the page uses the pack's cached stylesheets
    return new Response(
      '<!doctype html><html lang="en"><meta charset="utf-8">' +
      '<meta name="viewport" content="width=device-width,initial-scale=1">' +
      '<title>Offline &mdash; J.S. Warden</title>' +
      '<link rel="stylesheet" href="/fonts/fonts.css"><link rel="stylesheet" href="/tokens/themes.css">' +
      '<link rel="stylesheet" href="/css/base.css"><link rel="stylesheet" href="/css/site.css">' +
      '<script>(function(){var d=document.documentElement,t=null;' +
      'try{t=localStorage.getItem("jsw-theme")}catch(e){}t=(t==="light"||t==="casefile")?"light":"dark";d.setAttribute("data-theme",t)})();</script>' +
      '<body><main class="jsw-main" id="main"><div class="jsw-wrap">' +
      '<h1>You are offline</h1>' +
      '<p class="jsw-lede">This page has not been opened on this device yet, so there is no saved copy to show. ' +
      'The tabletop tools still work offline.</p>' +
      '<p><a class="jsw-btn" href="/tabletop/">Go to the tabletop tools</a></p>' +
      '</div></main>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } }
    );
  }

  self.addEventListener('fetch', function (e) {
    var req = e.request;
    if (req.method !== 'GET') return;
    var url = new URL(req.url);
    var sameOrigin = url.origin === self.location.origin;
    if (req.mode === 'navigate') { e.respondWith(networkFirst(e, req, PAGES)); return; }
    if (sameOrigin && CODE.test(url.pathname)) { e.respondWith(networkFirst(e, req, ASSETS)); return; }
    if (sameOrigin) { e.respondWith(staleWhileRevalidate(e, req)); }
  });
})();
'''

def font_files(root):
    out = []
    for css in sorted(glob.glob(os.path.join(root, '**', '*.css'), recursive=True)):
        rel_css = os.path.relpath(css, root).replace(os.sep, '/')
        if rel_css.startswith('css/studio/'): continue
        s = open(css, encoding='utf-8').read()
        if '@font-face' not in s: continue
        base = '/' + os.path.relpath(os.path.dirname(css), root).replace(os.sep, '/')
        for u in re.findall(r'url\(\s*[\'"]?([^\'")]+\.woff2)[\'"]?\s*\)', s):
            p = u if u.startswith('/') else os.path.normpath(os.path.join(base, u)).replace(os.sep, '/')
            if p not in out: out.append(p)
    return out

REF = re.compile(r'((?:href|src)=")((?!https?:|//)[^"?#]+\.(?:css|js))(?:\?v=[0-9a-f]+)?(")')

def file_hash(path):
    return hashlib.sha256(open(path, 'rb').read()).hexdigest()[:10]

def resolve(root, html_path, ref):
    """the file a CSS/JS reference in a page points to, or None"""
    if ref.startswith('/'): p = os.path.join(root, ref.lstrip('/'))
    else: p = os.path.normpath(os.path.join(os.path.dirname(html_path), ref))
    return p if os.path.isfile(p) else None


def expected(root):
    """What the site's generated parts should be: {relative path: text} for every page whose version tags
    are out of date, plus sw.js. Pure: reads root, writes nothing."""
    out = {}
    pages_text = {}
    for html in sorted(glob.glob(os.path.join(root, '**', '*.html'), recursive=True)):
        s = open(html, encoding='utf-8').read()
        def sub(m, html=html):
            f = resolve(root, html, m.group(2))
            return m.group(1) + m.group(2) + ('?v=' + file_hash(f) if f else '') + m.group(3)
        new = REF.sub(sub, s)
        pages_text[os.path.normpath(html)] = new
        if new != s: out[os.path.relpath(html, root).replace(os.sep, '/')] = new
    # tool folders by NAME (no path separators involved: on Windows glob's 'tabletop/*/' ends in a backslash)
    tools_root = os.path.join(root, 'tabletop')
    tool_names = sorted(n for n in os.listdir(tools_root) if os.path.isfile(os.path.join(tools_root, n, 'index.html'))) if os.path.isdir(tools_root) else []
    # the home page and the tabletop hub are precached once they exist (the skeleton has no pages yet)
    pages = [p for p in ['/', '/tabletop/'] if os.path.isfile(os.path.join(root, p.lstrip('/'), 'index.html'))]
    pages += ['/tabletop/%s/' % n for n in tool_names]
    assets = ['/site.webmanifest', '/fonts/fonts.css', '/tokens/themes.css', '/css/base.css', '/css/site.css',
              '/css/tool-parts.css', '/js/theme-switcher.js', '/js/site.js', '/assets/icons/icon-192.png']
    # the home page and the hub: the CSS/JS and images they load, so they render offline too
    for p in [p for p in pages if p in ('/', '/tabletop/')]:
        s = open(os.path.join(root, p.lstrip('/'), 'index.html'), encoding='utf-8').read()
        refs = re.findall(r'(?:href|src)="([^"#?]+\.(?:css|js))(?:\?[^"]*)?"', s)
        refs += [u.strip().split(' ')[0] for v in re.findall(r'(?:<img[^>]*\ssrc|srcset)="([^"]+)"', s) for u in v.split(',')]
        for ref in refs:
            if ref.startswith(('http', '//', 'data:')): continue
            a = ref if ref.startswith('/') else p + ref
            if a not in assets: assets.append(a)
    for name in tool_names:
        s = open(os.path.join(tools_root, name, 'index.html'), encoding='utf-8').read()
        for ref in re.findall(r'(?:href|src)="([^"#?]+\.(?:css|js))(?:\?[^"]*)?"', s):
            if ref.startswith('http'): continue
            a = ref if ref.startswith('/') else '/tabletop/%s/%s' % (name, ref) if not ref.startswith('../') else '/tabletop/' + ref[3:]
            if a not in assets: assets.append(a)
    for f in font_files(root):
        if f not in assets: assets.append(f)
    # every page stylesheet (small): the first page a visitor opens is saved on activation, and its own CSS must be
    # here too, since it loaded before this worker took over (review, stage 2)
    for f in sorted(glob.glob(os.path.join(root, 'css', 'pages', '*.css'))):
        a = '/css/pages/' + os.path.basename(f)
        if a not in assets: assets.append(a)
    path_of = lambda a: os.path.join(root, a.lstrip('/') + ('index.html' if a.endswith('/') else ''))
    missing = [a for a in pages + assets if not os.path.isfile(path_of(a))]
    if missing: raise SystemExit('build_sw: files the service worker must precache are missing: %s' % missing)
    def content(a):   # pages as they will be once their version tags are current
        p = os.path.normpath(path_of(a))
        return pages_text[p].encode('utf-8') if p in pages_text else open(p, 'rb').read()
    h = hashlib.sha256(TEMPLATE.encode('utf-8'))
    for a in pages + assets:
        h.update(a.encode('utf-8')); h.update(b'\0'); h.update(content(a)); h.update(b'\0')
    version = h.hexdigest()[:12]
    asset_urls = [a + ('?v=' + file_hash(path_of(a)) if a.endswith(('.css', '.js')) else '') for a in assets]
    ind = lambda xs: json.dumps(xs, indent=4, ensure_ascii=False).replace('\n', '\n  ')
    sw = TEMPLATE % {'host': HOST, 'version': version, 'pages': ind(pages), 'assets': ind(asset_urls)}
    assert '#ffffff' not in sw.lower()
    cur = open(os.path.join(root, 'sw.js'), encoding='utf-8').read() if os.path.exists(os.path.join(root, 'sw.js')) else None
    if cur != sw: out['sw.js'] = sw
    return out, {'version': version, 'pages': len(pages), 'assets': len(assets), 'fonts': len(font_files(root))}

def build(root=None):
    root = root or REPO
    todo, info = expected(root)
    for rel, text in todo.items():
        with open(os.path.join(root, rel), 'w', encoding='utf-8', newline='\n') as fh: fh.write(text)
    info['files_written'] = sorted(todo)
    return info

def check(root=None):
    todo, info = expected(root or REPO)
    return sorted(todo), info

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

if __name__ == '__main__':
    args = sys.argv[1:]
    if args[:1] == ['--check']:
        stale, info = check(args[1] if len(args) > 1 else None)
        if stale:
            print('build_sw: OUT OF DATE (%d file%s): %s' % (len(stale), '' if len(stale) == 1 else 's', ', '.join(stale[:12]) + (' ...' if len(stale) > 12 else '')))
            print('build_sw: run  python3 .github/build_sw.py  (Windows: py -3 .github/build_sw.py)  then  git add -A  and commit again.')
            sys.exit(1)
        print('build_sw: version tags and sw.js are up to date (service worker %s).' % info['version'])
    else:
        info = build(args[0] if args else None)
        print('build_sw: %s' % info)
